"""Compile model data and the image attribution page; no network at runtime."""
from pathlib import Path
import json,html
models=json.loads(Path('commerce-models.json').read_text());credits=[];art_by_model={}
for manifest in [Path('img/commerce/import-illustrations-v1.json')]+sorted(Path('img/commerce').glob('dealer-showroom-v*.json')):
 atlas=json.loads(manifest.read_text())
 for index,key in enumerate(atlas['models']):
  art={k:atlas[k] for k in ['width','height','columns','rows']}
  art.update(src=atlas['image'],column=index%atlas['columns'],row=index//atlas['columns'],kind=atlas.get('kind','drawing'))
  if key in atlas.get('regions',{}):art['region']=atlas['regions'][key]
  art_by_model[key]=art
for m in models:
 p=Path('img/commerce')/(m['key']+'.webp');meta=p.with_suffix('.json')
 m['photo']=str(p) if p.exists() else ''
 if m['key'] in art_by_model:m['illustration']=art_by_model[m['key']]
 if meta.exists():credits.append(json.loads(meta.read_text()))
Path('commerce-models.js').write_text("'use strict';\n// Generated by scripts/build-commerce-models.py. Prices and stock are game data.\nvar COMMERCE_MODELS="+json.dumps([{k:v for k,v in m.items() if k in ['key','kind','brand','model','price','engine','body','country','minYear','photo','illustration','variant']} for m in models],ensure_ascii=False,separators=(',',':'))+';\n')
rows=''.join('<tr><td>'+html.escape(c['model'])+'</td><td><a href="'+html.escape(c['source'],quote=True)+'">'+html.escape(c['file'])+'</a></td><td>'+html.escape(c['author'])+'</td><td><a href="'+html.escape(c['licenseUrl'],quote=True)+'">'+html.escape(c['license'])+'</a></td></tr>' for c in credits)
Path('commerce-photo-credits.html').write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><title>Фотографии моделей — Perekup.ru</title><style>body{font:15px system-ui;max-width:1100px;margin:30px auto;padding:20px}td,th{padding:12px;text-align:left;border-bottom:1px solid #ddd;overflow-wrap:anywhere}table{width:100%}</style><h1>Фотографии моделей</h1><p>Снимки моделей используются как иллюстрации. Цвет, комплектация и состояние игрового экземпляра указаны отдельно. Снимки уменьшены и перекодированы в WebP; исходные лицензии сохраняются. Данные каталога и цены являются игровыми. В текущем импорте показаны фотореалистичные изображения моделей на улицах Москвы, созданные инструментом image_gen; заводской цвет выбирается до заказа, детали комплектации условны. Все текущие модели автосалона показаны на фотореалистичных изображениях в едином салонном окружении, созданных инструментом image_gen. Это иллюстрации моделей, а не фотографии конкретных экземпляров. Атрибуции ниже сохранены для прежних фотографий моделей.</p><table><tr><th>Модель</th><th>Источник</th><th>Автор</th><th>Лицензия</th></tr>'+rows+'</table></html>')
print(len(models),'models;',len(credits),'photos')
